package com.bananalab.lite;
import android.app.*;import android.graphics.*;import android.text.*;import android.widget.*;
/** Local source editor for the bounded behavior language. */
final class RuntimeWorkshop{
 interface Commands{void send(String text);}
 static void show(Activity a,Commands commands){UiTypeface.show(new AlertDialog.Builder(a).setTitle("Taller · actualizaciones locales").setItems(new String[]{"Estado y diagnóstico","Ver código activo","Editar código activo","Editar borrador","Preparar módulo de ejemplo","Probar borrador","Probar y activar ahora","Volver a revisión anterior","Reparar un pedido","Activar/pausar reparación automática","Ayuda y alcance"},(d,i)->{if(i==0)commands.send("estado de modulos");else if(i==1)editor(a,commands,false,false);else if(i==2)editor(a,commands,true,false);else if(i==3)editor(a,commands,true,true);else if(i==4)commands.send("prepara ejemplo de modulo");else if(i==5)commands.send("prueba modulos");else if(i==6)commands.send("activa modulos");else if(i==7)commands.send("revierte modulos");else if(i==8){EditText input=new EditText(a);input.setTextColor(Color.BLACK);input.setHint("el zorro le de un besito a la banana");input.setText(RuntimeModules.prefs(a).getString("lastRequest",""));input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(400)});UiTypeface.show(new AlertDialog.Builder(a).setTitle("Pedido para reparar").setView(input).setPositiveButton("Reparar y probar",(x,y)->commands.send("repara este pedido: "+input.getText().toString())).setNegativeButton("Cancelar",null));}else if(i==9)commands.send(RuntimeModules.prefs(a).getBoolean("autoRepair",true)?"pausa reparacion local":"activa reparacion local");else UiTypeface.show(new AlertDialog.Builder(a).setTitle("Qué cambia en vivo").setMessage("Editás código JSON de comportamientos. Guardar crea un borrador; probar y activar ejecuta sus pruebas y lo cambia para el próximo pedido, sin reinstalar. Si una prueba falla, sigue la revisión anterior.\n\nPodés componer baile, salto, saludo, giro, aplauso, espera, caminar, mirar, acercarse y el beso ya implementado. No compila Java, no cambia los modelos ni crea una animación arbitraria. El reparador automático reconoce algunas frases de beso o festejo.\n\nEjemplo tras activarlo: Fito celebra con Bani. Para cambiar la secuencia abrí Editar código activo. Los parámetros de pruebas son Fito (zorro) y Bani (banana).").setPositiveButton("Cerrar",null));}).setNegativeButton("Cerrar",null));}
 static void editor(Activity a,Commands commands,boolean edit,boolean draft){String raw=draft?RuntimeModules.candidate(a):RuntimeModules.code(a);if(raw.isEmpty())raw=RuntimeModules.code(a);final int base=draft&&!RuntimeModules.candidate(a).isEmpty()?RuntimeModules.prefs(a).getInt("candidateBase",-1):RuntimeModules.revision(a);try{raw=new org.json.JSONObject(raw).toString(2);}catch(Exception ignored){}LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(18,8,18,8);TextView info=new TextView(a);info.setTextColor(Color.BLACK);info.setText("Revisión base "+base+" · "+(edit?"Guardar no activa. Después probá y activá desde el taller.":"Este es el código que interpreta el motor local."));box.addView(info);EditText source=new EditText(a);source.setTextColor(Color.BLACK);source.setBackgroundColor(Color.WHITE);source.setTypeface(Typeface.MONOSPACE);source.setTextSize(12);source.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);source.setMinLines(12);source.setFilters(new InputFilter[]{new InputFilter.LengthFilter(32768)});source.setText(raw);source.setSelection(0);if(!edit){source.setKeyListener(null);source.setTextIsSelectable(true);}box.addView(source);ScrollView scroll=new ScrollView(a);scroll.addView(box);AlertDialog.Builder builder=new AlertDialog.Builder(a).setTitle(edit?"Código del módulo · JSON":"Código activo · lectura").setView(scroll).setNegativeButton("Cerrar",null);if(edit)builder.setPositiveButton("Guardar borrador",null);AlertDialog dialog=builder.create();if(edit)dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{RuntimeModules.stage(a,source.getText().toString(),base);dialog.dismiss();commands.send("estado de modulos");}catch(Exception e){Toast.makeText(a,e.getMessage(),Toast.LENGTH_LONG).show();}}));dialog.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);UiTypeface.show(dialog);}
}
